    const k = 2 * Math.PI / lambdaOf(E);
    const cos2 = Math.cos(theta) ** 2;
    const kz = n => { const n2 = C.mul(n, n); return C.scale(C.sqrt([n2[0] - cos2, n2[1]]), k); };
    const kzV = [k * Math.sin(theta), 0];
