    const sc = Math.sin(chi) * Math.cos(chi), dsp = Math.cos(chi) ** 2 - nu * Math.sin(chi) ** 2;
    const psiIn = th + chi, psiOut = th - chi;
    // angular gradients (per unit depth) along the incident and diffracted ray paths
    const rotIn = Math.tan(psiIn) + (1 + nu) * sc;      // lattice rotation seen along incident path
    const rotOut = Math.tan(psiOut) - (1 + nu) * sc;    // ... along diffracted path
    const dspTerm = dsp * Math.tan(th);                 // Bragg-angle change from d-spacing gradient
    const aR = Math.abs(R);
    const dthIn = T / aR * Math.abs(rotIn + dspTerm);   // range of Bragg deviation sampled by one incident ray
    const dthOut = T / aR * Math.abs(rotOut + dspTerm); // ... by one exit ray (energy spread at a point)
    const dEE_dsp = T / aR * Math.abs(dsp);             // d-spacing part alone (Qi et al. eq. 12)
    // footprint (polychromatic) term: change of glancing angle along the surface
    const p = o.p_m == null ? Infinity : o.p_m * 1e10;
    const foot = (o.beam_mm || 0) * 1e7 / Math.cos(psiIn); // footprint length along surface, A
    const dgdx = 1 / R + (isFinite(p) ? Math.cos(psiIn) / p : 0);
