    const Q = Math.PI * Math.PI * sq2 * S.Cpol * S.Cpol / (S.lam * Math.sin(2 * th)); // kinematic, per A
    const L = T / S.g0;
    const absorb = Math.exp(-S.mu_cm * 1e-8 * T * 0.5 * (1 / S.g0 + 1 / S.gh));
    const Rpeak = 0.5 * (1 - Math.exp(-2 * Q * L / dthEff)) * absorb;
    const Rint = Rpeak * dthEff;
